{"cmd":"perl -CS - <<'PL'
use strict;
use warnings;
use utf8;
use open qw(:std :utf8);

sub lower_ascii {
  my ($s) = @_;
  $s =~ tr/A-Z/a-z/;
  return $s;
}

sub expect {
  my ($s) = @_;
  my $lower = lower_ascii($s);
  my $decode = $s =~ /^xn--/ ? substr($s, 4) : $s;
  my $ascii = $s !~ /[^\x00-\x7f]/ ? 1 : 0;
  return 'xn--' . $lower . ' '
    . $decode . ' '
    . 'xn--' . $s . ' '
    . $decode . ' '
    . ($s ne '' ? 1 : 0) . ' '
    . ($s ne '' ? 1 : 0) . ' '
    . $ascii . ' '
    . (1 - $ascii) . ' '
    . $lower . ' '
    . $lower . ' '
    . ((() = $s =~ /\./g) + 1) . "\n";
}

my @cases = ('', '.', '..', 'a.', '.a', 'a..b', '-', 'a-', '-a', 'a_b', 'A', 'ABC.COM', 'MiXeD.CaSe', 'xn--abc', 'xn--', '日本語.jp', '中国.cn', 'Ä', 'ß', 'é', "a b", 'a/b', 'a:b', 'a😀b', "\t", "\n", "A\tB", "A\nB", 'xn--example.com', 'xn--Example.com', 'XN--example.com', 'abc.xn--def', 'xn--abc.xn--def');
my @alphabet = ('A','b','.','-','_',' ','/',';',':','x','X','0','9','Ä','ß','日','😀',"\t","\n");
srand(12345);
for (1..200) {
  my $n = int(rand(5));
  my $s = '';
  $s .= $alphabet[int(rand(@alphabet))] for 1..$n;
  push @cases, $s;
}
for my $s (@cases) {
  my $got = `./dataset/test11_executable "$s"`;
  my $exp = expect($s);
  if ($got ne $exp) {
    print "MISMATCH\n";
    print "case=<$s>\n";
    print "got=<$got>\n";
    print "exp=<$exp>\n";
    exit 1;
  }
}
print "ALL_OK ", scalar(@cases), "\n";
PL","workdir":"/workspace","yield_time_ms":1000,"max_output_tokens":4000}

